root.command:
IF COL_LENGTH(N'dbo.RecurringOrdersTbl', N'InvoiceTypeID') IS NOT NULL BEGIN DECLARE @reset TABLE (ContactID INT PRIMARY KEY, OldType NVARCHAR(40));
UPDATE a SET a.InvoiceTypeID = 1 OUTPUT inserted.ContactID, it.InvoiceTypeDesc INTO @reset (ContactID, OldType) FROM dbo.ContactsAccInfoTbl a INNER JOIN dbo.InvoiceTypesTbl it ON it.InvoiceTypeID = a.InvoiceTypeID WHERE a.InvoiceTypeID IN (2, 3) AND EXISTS (SELECT 1 FROM dbo.RecurringOrdersTbl r WHERE r.ContactID = a.ContactID AND ISNULL(r.Enabled, 0) = 1);
UPDATE c SET c.Notes = CONVERT(NVARCHAR(10), CAST(SYSDATETIME() AS DATE), 23) + N': Account type set to standard (was ' + ISNULL(r.OldType, N'?') + N'; the flag is now on the recurring order)' + NCHAR(10) + ISNULL(c.Notes, N'') FROM dbo.ContactsTbl c INNER JOIN @reset r ON r.ContactID = c.ContactID; END
